  var e = document.createElementNS(NS, tag);
  for (var k in attrs) e.setAttribute(k, attrs[k]);
  if (txt !== undefined) e.textContent = txt;
  return e;
}
function computePillWidth(t, fs){ return Math.ceil(t.length * fs * 0.58) + 10; }
var FONT = "-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif";
var svg = document.createElementNS(NS, "svg");
svg.setAttribute("viewBox","0 0 680 300");
svg.setAttribute("width","100%");
var W = 680, H = 300;
var margin = {left:62, right:24, top:18, bottom:46};
var PW = W - margin.left - margin.right;
var PH = H - margin.top - margin.bottom;
var MT = margin.top;
var series = [
  {name:"IPC GLOBAL", color:"#4a5568", sw:"2", off:-10, v:[1.7,1.7,1.9,1.7,1.9,2.4,2.2,2.2,2.4,2.3,1.8,2.4,2.8,3.2,2.8,3.0,3.0,3.1]},
  {name:"IPC-MÉDIAN", color:"#9ca3af", sw:"1.6", off:-15, v:[3.1,2.9,2.9,3.0,3.0,3.1,2.9,2.8,2.6,2.5,2.3,2.3,2.1,2.1,1.9,2.0,2.0,1.9]},
  {name:"IPC-TRONQUÉ", color:"#6b7280", sw:"1.6", off:12, v:[3.1,3.0,3.1,3.1,3.0,3.1,3.0,2.9,2.7,2.4,2.3,2.2,2.0,2.0,1.9,1.9,1.9,1.8]}
];
var n = series[0].v.length;
var all = [];
series.forEach(function(s){ all = all.concat(s.v); });
var lo = Math.min.apply(null, all), hi = Math.max.apply(null, all);
var yMin = Math.floor(lo - 1), yMax = Math.ceil(hi + 1);
function xp(i){ return margin.left + (i / (n - 1)) * PW; }
function yp(v){ return MT + (yMax - v) / (yMax - yMin) * PH; }
var xLabels = {0:"avr. 25", 5:"sept. 25", 9:"janv. 26", 13:"mai 26", 17:"sept. 26"};
var bandStart = 11, bandEnd = n - 1;
var refVal = 2;
var refY = yp(refVal);
var lastX = xp(n - 1);

// 0. event band
svg.appendChild(el("rect", {x: xp(bandStart), y: MT, width: xp(bandEnd) - xp(bandStart), height: PH, fill: "#2e7d32", "fill-opacity": "0.07"}));
// 1. gridlines and y labels
for (var t = yMin; t <= yMax; t += 1) {
  svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: yp(t), y2: yp(t), stroke: "#ececec", "stroke-width": "0.5"}));
  svg.appendChild(el("text", {x: margin.left - 6, y: yp(t) + 3, "text-anchor": "end", "font-size": "8.5", fill: "#aaaaaa", "font-family": FONT}, t + " %"));
}
// 2. reference line
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: refY, y2: refY, stroke: "#2e7d32", "stroke-width": "1", "stroke-dasharray": "3,3"}));
// 3. series paths (core first, total on top)
function pathFor(vals){
  var d = "";
  for (var i = 0; i < vals.length; i++) d += (i === 0 ? "M" : "L") + xp(i).toFixed(1) + " " + yp(vals[i]).toFixed(1) + " ";
  return d;
}
[series[1], series[2], series[0]].forEach(function(s){
  svg.appendChild(el("path", {d: pathFor(s.v), fill: "none", stroke: s.color, "stroke-width": s.sw, "stroke-linejoin": "round"}));
});
// 4. axis lines
svg.appendChild(el("line", {x1: margin.left, x2: margin.left, y1: MT, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": "1"}));
svg.appendChild(el("line", {x1: margin.left, x2: margin.left + PW, y1: MT + PH, y2: MT + PH, stroke: "#d8d8d8", "stroke-width": "1"}));
// 5. endpoint dots (every labelled series carries one)
series.forEach(function(s){
  svg.appendChild(el("circle", {cx: lastX, cy: yp(s.v[n - 1]), r: 3, fill: s.color}));
});
// 6. pill below the total CPI endpoint, left of it
var headEnd = series[0].v[n - 1];
var headY = yp(headEnd);
var pillText = headEnd.toFixed(1).replace(".", ",") + " %";
var pillW = computePillWidth(pillText, 9);
var pillH = 16;
var pillX = lastX - pillW - 6;
if (pillX < margin.left) pillX = margin.left;
var pillY = headY + 10;
svg.appendChild(el("rect", {x: pillX, y: pillY, width: pillW, height: pillH, rx: 3, fill: "#e8a825"}));
svg.appendChild(el("text", {x: pillX + pillW / 2, y: pillY + pillH / 2 + 3, "text-anchor": "middle", "font-size": "9", "font-weight": "700", fill: "#111111", "font-family": FONT}, pillText));
// 7. labels and annotations
series.forEach(function(s){
  svg.appendChild(el("text", {x: lastX - 4, y: yp(s.v[n - 1]) + 3 + s.off, "text-anchor": "end", "font-size": "7.5", "font-weight": "700", fill: "#444444", "font-family": FONT}, s.name));
});
svg.appendChild(el("text", {x: margin.left + 10, y: refY - 10, "text-anchor": "start", "font-size": "7", "font-weight": "700", fill: "#2e7d32", "font-family": FONT}, "CIBLE 2 %"));
svg.appendChild(el("text", {x: (xp(bandStart) + xp(bandEnd)) / 2, y: MT + 12, "text-anchor": "middle", "font-size": "7", "font-weight": "700", fill: "#2e7d32", "font-family": FONT}, "GLOBAL AU-DESSUS, 7 MOIS"));
var lgX = margin.left + 10, lgY = MT + 12, lgStep = 84;
var legendOrder = [series[0], series[2], series[1]];
legendOrder.forEach(function(s, idx){
  var bx = lgX + idx * lgStep;
  svg.appendChild(el("line", {x1: bx, x2: bx + 10, y1: lgY - 3, y2: lgY - 3, stroke: s.color, "stroke-width": s.sw}));
  svg.appendChild(el("text", {x: bx + 14, y: lgY, "text-anchor": "start", "font-size": "7.5", fill: "#888888", "font-family": FONT}, s.name));
});
for (var k in xLabels) {
  var kx = xp(+k);
  var ka = (+k === n - 1) ? "end" : "middle";
  svg.appendChild(el("text", {x: kx, y: MT + PH + 14, "text-anchor": ka, "font-size": "8", fill: "#999999", "font-family": FONT}, xLabels[k]));
}
_cs.parentNode.appendChild(svg);
})();
</script>
</div>
<div style="font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;font-size:10px;color:#999;padding:4px 14px 10px;font-style:italic;">Source&nbsp;: Banque du Canada, tableau de l’IPC et des mesures de l’inflation fondamentale (données de Statistique Canada), publication de septembre 2026. &nbsp;|&nbsp; hdq.ca</div>
</div>
</div>
<p style="font-size:11px;color:#666;font-family:-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif;margin-top:6px;">L’IPC-tronqué et l’IPC-médian sont les mesures de l’inflation fondamentale privilégiées par la Banque du Canada, présentées en données désaisonnalisées. La zone ombragée marque les sept mois consécutifs, de mars à septembre 2026, où l’IPC global a dépassé les deux.</p>
<h2>Un marché du travail qui va dans l’autre sens</h2>
<p>Les données d’emploi vont dans la direction opposée. Statistique Canada a indiqué le 9 octobre que l’économie avait perdu net 68&nbsp;300 emplois en septembre, alors que le consensus prévoyait un gain de 9&nbsp;200, après une perte de 41&nbsp;700 en août. Le taux de chômage est passé à 6,5&nbsp;% contre 6,4&nbsp;%. La variation depuis le début de l’année est une perte nette de 41&nbsp;200 emplois, comparativement à un gain de 211&nbsp;300 sur la même période de 2025.</p>
<p>La composition compte. Le secteur manufacturier, en partie exposé aux droits de douane américains, a perdu 12&nbsp;700 emplois, et l’emploi dans le secteur public a fortement reculé dans les soins de santé, l’assistance sociale et l’éducation. Le taux d’activité a perdu 0,2 point à 64,8&nbsp;%, son plus bas niveau en 29 ans hors pandémie. Le salaire horaire moyen des employés permanents a augmenté de 2,3&nbsp;% sur un an, contre 2,0&nbsp;% en août.</p>
<p>Royce Mendes, de Desjardins, a déclaré après la publication du rapport que la faiblesse du marché du travail rendait un statu quo probable, les prix de l’énergie pouvant justifier un resserrement prochain. La Banque a reconnu qu’un large éventail d’indicateurs montre encore une offre excédentaire et que le taux de chômage se maintient autour de 6,5&nbsp;% depuis plusieurs mois. Elle a choisi d’agir sur le front des prix.</p>
<h2>La transmission aux emprunteurs et le test de décembre</h2>
<p>Le mécanisme passe par le taux préférentiel et les rendements obligataires. Le taux préférentiel passe de 4,45&nbsp;% à 4,70&nbsp;% dans les grandes banques. Sur un prêt hypothécaire à taux variable de 500&nbsp;000&nbsp;$ au taux préférentiel moins 0,50&nbsp;% avec une période d’amortissement de 25 ans, le versement mensuel passe d’environ 2&nbsp;617&nbsp;$ à 2&nbsp;685&nbsp;$, soit environ 816&nbsp;$ par année. Les taux fixes suivent les rendements obligataires, et les rendements à deux ans ont augmenté de plus de 0,22 point de pourcentage entre les décisions de septembre et d’octobre. Doug Porter, économiste en chef de BMO, a déclaré que la situation avait dépassé la zone de confort de la Banque.</p>
<p>Les marchés anticipent quatre hausses d’un quart de point d’ici la fin de 2027, y compris celle du 28 octobre, ce qui porterait le taux directeur à 3,25&nbsp;%. Dans un sondage Reuters auprès de 29 économistes réalisé du 21 au 23 octobre, 16 s’attendaient à une autre hausse avant la fin de mars 2027. La Réserve fédérale a maintenu son taux à une fourchette de 3,75&nbsp;% à 4,00&nbsp;% le 28 octobre par 10 voix contre 2, la gouverneure Lisa Cook et la présidente de la Fed de Cleveland, Beth Hammack, ayant exprimé leur dissidence en faveur d’une hausse.</p>
<p>Le mouvement du pétrole du 4 novembre touche directement la thèse de la Banque. Le WTI a réglé en baisse de 8,29&nbsp;% à 88,12&nbsp;$&nbsp;US et le Brent a reculé de 8,67&nbsp;% à 94,62&nbsp;$&nbsp;US après que le vice-président JD Vance a attribué à la guerre en Iran les défaites républicaines aux élections de mi-mandat. La déclaration de la Banque supposait que les prix resteraient élevés plus longtemps. Une séance ne tranche pas cette hypothèse, mais une baisse soutenue affaiblirait la thèse de la transmission avant la décision du 9 décembre, alors que deux publications de l’IPC et deux rapports sur l’emploi restent à venir.</p>
',
  '<div class="toolkit-section">
<div class="toolkit-section-label">Ce qu’ils ressentent</div>
<p>Les emprunteurs à taux variable ressentent d’abord l’augmentation de leur versement, puis l’explication. Les clients qui approchent d’un renouvellement hypothécaire craignent que la trajectoire des taux pointe encore vers le haut. Les épargnants sont discrètement satisfaits de voir les taux des dépôts et des CPG augmenter. Les retraités à revenu fixe surveillent une inflation globale de 3,1&nbsp;% et se demandent si leur pouvoir d’achat s’érode.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Quoi dire</div>
<div class="script-box">La Banque du Canada a relevé son taux d’un quart de point à 2,5&nbsp;% le 28 octobre, sa première hausse depuis 2023. La raison est l’énergie. L’inflation globale est de 3,1&nbsp;% parce que l’essence a augmenté de presque 28&nbsp;% sur un an, mais les mesures de l’inflation sous-jacente de la Banque sont inférieures à 2&nbsp;%. La Banque relève ses taux parce qu’elle s’attend à ce que les coûts de l’énergie se répercutent sur les autres prix au cours de l’année à venir, et elle a dit que d’autres hausses pourraient être nécessaires. En même temps, le marché du travail s’est affaibli, et le pétrole a reculé de plus de 8&nbsp;% mercredi. La prochaine décision, le 9 décembre, est donc réellement ouverte. Ce que j’aimerais faire, c’est examiner votre prêt hypothécaire et vos flux de trésorerie selon deux scénarios, l’un où les taux montent de nouveau et l’autre où ils restent stables, afin que rien au sujet de décembre ne vous surprenne.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Qui est touché</div>
<p><strong>Forte incidence&nbsp;:</strong> Emprunteurs hypothécaires et titulaires de marges de crédit hypothécaires à taux variable, dont les versements ont déjà augmenté. Clients qui renouvellent un prêt hypothécaire à taux fixe au cours des 12 prochains mois. Propriétaires d’entreprise ayant une dette à taux flottant.</p>
<p><strong>Incidence variable&nbsp;:</strong> Portefeuilles équilibrés, où des rendements plus élevés aident les nouveaux achats d’obligations, mais font baisser le prix des obligations existantes. Retraités détenant un mélange de titres à revenu fixe et de CPG.</p>
<p><strong>Avantage potentiel&nbsp;:</strong> Épargnants détenant des liquidités, des comptes d’épargne à intérêt élevé et des CPG à court terme, et clients qui achètent une première rente ou réinvestissent des obligations échues à des rendements plus élevés.</p>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Liste de vérification</div>
<div class="checklist-item">Dresser la liste de chaque client ayant un prêt hypothécaire ou une marge de crédit hypothécaire à taux variable et calculer la variation du versement découlant de la hausse du 28 octobre.</div>
<div class="checklist-item">Repérer les clients dont l’hypothèque à taux fixe vient à échéance dans les 12 prochains mois et noter la date de renouvellement.</div>
<div class="checklist-item">Modéliser une deuxième hausse de 25 points de base et un statu quo pour les flux de trésorerie mensuels de chaque client signalé.</div>
<div class="checklist-item">Examiner l’échelonnement des échéances des CPG et des obligations et signaler les échéances qui peuvent être réinvesties à des rendements plus élevés.</div>
<div class="checklist-item">Inscrire à l’agenda la décision de la Banque du Canada du 9 décembre ainsi que les prochaines publications de l’IPC et de l’emploi qui la précèdent.</div>
</div>
<div class="toolkit-section">
<div class="toolkit-section-label">Modèle de courriel de suivi</div>
<div class="email-box" id="respond-email">
