// 7. labels
svg.appendChild(el("text", {x: lastX, y: refY + 14, "text-anchor": "end", "font-size": "7", "font-weight": "700", fill: "#6b7280", "font-family": FONT}, "AVANT-GUERRE " + refVal.toFixed(2).replace(".", ",") + " $"));
svg.appendChild(el("text", {x: xp(warIdx) + 5, y: MT + 12, "text-anchor": "start", "font-size": "7", "font-weight": "700", fill: "#1a3560", "font-family": FONT}, "GUERRE, 28 FÉVR."));
svg.appendChild(el("text", {x: lastX - 5, y: MT + 12, "text-anchor": "end", "font-size": "7", "font-weight": "700", fill: "#1a3560", "font-family": FONT}, "4 NOV. -8,7 %"));
svg.appendChild(el("text", {x: (xp(hormuzIdx) + lastX) / 2, y: MT + PH - 8, "text-anchor": "middle", "font-size": "7", "font-weight": "700", fill: "#8a3030", "font-family": FONT}, "ORMUZ RESTREINT DEPUIS DÉBUT MARS"));
for (var j = 0; j < n; j++) {
  var ta = (j === lastI) ? "end" : "middle";
  svg.appendChild(el("text", {x: xp(j), y: MT + PH + 14, "text-anchor": ta, "font-size": "8", fill: "#999999", "font-family": FONT}, xl[j]));
}
_cs.parentNode.appendChild(svg);
})();
</script>
